class ConfigError(Exception):
    pass
def load_port(text):
    try:
        return int(text)
    except ValueError as error:
        raise ConfigError('port must be an integer') from error
try:
    load_port('web')
except ConfigError as error:
    print(type(error).__name__)
    print(type(error.__cause__).__name__)

try:
    try:
        int('invalid')
    except ValueError as error:
        raise RuntimeError('could not load setting') from error
except RuntimeError as error:
    print(str(error))
    print(type(error.__cause__).__name__)

try:
    try:
        int('bad')
    except ValueError:
        raise RuntimeError('configuration rejected') from None
except RuntimeError as error:
    print(str(error))
    print(error.__cause__)

def parse(text):
    try:
        value = int(text)
    except ValueError:
        return None
    return value * 10
print(parse('4'))
print(parse('x'))

try:
    1 / 0
except ZeroDivisionError:
    print('Cannot calculate this result')
print('application continues')
